on conflict (app_id, country_code) where plan_id is null do update set
  price=excluded.price, currency=excluded.currency, updated_at=excluded.updated_at,
  source_type=excluded.source_type, source_name=excluded.source_name,
  source_url=excluded.source_url, confidence_level=excluded.confidence_level,
  last_verified_at=excluded.last_verified_at;

-- ============================================================
-- Non-default plan prices (plan_id explicitly set)
-- Requires migration 009 (partial unique indexes on current_prices).
-- Top 10 most user-visible non-default plans × 20 countries.
-- Prices derived from default-plan country ratios + plan tier ratios.
-- ============================================================

insert into current_prices
  (app_id, country_code, plan_id, price, currency, updated_at,
   source_type, source_name, source_url, confidence_level, last_verified_at)
